":"2026-10-31T23:20:25.930158+00:00"},{"articulation":null,"battery":"hyrox_v3","battery_order":5,"battery_session":"S3","category":"hyrox","created_at":"2026-10-31T23:20:25.930158+00:00","created_by":null,"description":"Force et contrôle du genou sur une jambe, gauche et droite.","fill_mode":"self","id":"00000000-0000-0000-0000-0000000000dc","is_global":true,"kind":"preset","media_url":null,"name":"Assis-debout 1 jambe","protocol":{"text":"Box à hauteur de genou. Se lever et s''asseoir sur une jambe, sans élan ni appui de l''autre pied, jusqu''à l''échec. Gauche puis droite.","video":"De face, chaque côté."},"updated_at":"2026-10-31T23:20:25.930158+00:00"},{"articulation":null,"battery":"hyrox_v3","battery_order":6,"battery_session":"S3","category":"hyrox","created_at":"2026-10-31T23:20:25.930158+00:00","created_by":null,"description":"Saut en longueur sur une jambe, gauche et droite.","fill_mode":"self","id":"00000000-0000-0000-0000-0000000000dd","is_global":true,"kind":"preset","media_url":null,"name":"Hop 1 jambe","protocol":{"text":"Départ et réception sur la même jambe, réception tenue 2 s. 3 essais par côté, garder le meilleur. Gauche puis droite.","video":"De profil, chaque côté."},"updated_at":"2026-10-31T23:20:25.930158+00:00"},{"articulation":null,"battery":"hyrox_v3","battery_order":1,"battery_session":"S4","category":"hyrox","created_at":"2026-10-31T23:20:25.930158+00:00","created_by":null,"description":"3 passages de 12,5 m à 80, 100 et 120 % de la charge de course : vitesse à charge de course, charge max estimée, réserve de force.","fill_mode":"self","id":"00000000-0000-0000-0000-0000000000de","is_global":true,"kind":"preset","media_url":null,"name":"Sled Push : profil charge-vitesse","protocol":{"text":"Échauffement : quelques poussées légères. Puis 12,5 m le plus vite possible à 80 %, 100 % et 120 % de la charge de course de sa catégorie (sled compris), 2 min de récupération complète entre les passages. Même sled et même sol au retest. Noter la charge et le temps de chaque passage.","video":"De face ou de profil, départ et arrivée visibles (chrono à la vidéo)."},"updated_at":"2026-10-31T23:20:25.930158+00:00"},{"articulation":null,"battery":"hyrox_v3","battery_order":2,"battery_session":"S4","category":"hyrox","created_at":"2026-10-31T23:20:25.930158+00:00","created_by":null,"description":"3 passages de 12,5 m à 80, 100 et 120 % de la charge de course.","fill_mode":"self","id":"00000000-0000-0000-0000-0000000000df","is_global":true,"kind":"preset","media_url":null,"name":"Sled Pull : profil charge-vitesse","protocol":{"text":"Même protocole que le Sled Push : 12,5 m à 80 %, 100 % et 120 % de la charge de course, 2 min de récupération complète. Noter la charge et le temps de chaque passage.","video":"De profil, départ et arrivée visibles."},"updated_at":"2026-10-31T23:20:25.930158+00:00"},{"articulation":null,"battery":"hyrox_v3","battery_order":3,"battery_session":"S4","category":"hyrox","created_at":"2026-10-31T23:20:25.930158+00:00","created_by":null,"description":"2000 m au SkiErg, damper 4.","fill_mode":"self","id":"00000000-0000-0000-0000-0000000000e0","is_global":true,"kind":"preset","media_url":null,"name":"SkiErg 2000 m (damper 4)","protocol":{"text":"Damper 4, toujours. Départ arrêté, 2000 m à fond. Noter le temps affiché.","video":"Photo de l''écran à l''arrivée."},"updated_at":"2026-10-31T23:20:25.930158+00:00"},{"articulation":null,"battery":"hyrox_v3","battery_order":4,"battery_session":"S4","category":"hyrox","created_at":"2026-10-31T23:20:25.930158+00:00","created_by":null,"description":"Suspension passive à la barre : grip.","fill_mode":"self","id":"00000000-0000-0000-0000-0000000000e1","is_global":true,"kind":"preset","media_url":null,"name":"Dead hang","protocol":{"text":"En dernier dans la séance. Barre de traction, prise en pronation largeur d''épaules, bras tendus, suspension passive jusqu''au lâcher. Même barre au retest. Noter le temps.","video":"De face, du départ au lâcher."},"updated_at":"2026-10-31T23:20:25.930158+00:00"},{"articulation":null,"battery":"hyrox_v3","battery_order":1,"battery_session":"S5","category":"hyrox","created_at":"2026-10-31T23:20:25.930158+00:00","created_by":null,"description":"80 m de BBJ le plus vite possible, au standard de course.","fill_mode":"self","id":"00000000-0000-0000-0000-0000000000e2","is_global":true,"kind":"preset","media_url":null,"name":"Burpee broad jump 80 m · bilan","protocol":{"text":"80 m au standard de course. Compter les sauts (longueur moyenne). Noter le temps, le nombre de sauts, l''effort ressenti sur 10 et la FC 1 min après.","video":"De profil, tout le test (no-reps)."},"updated_at":"2026-10-31T23:20:25.930158+00:00"},{"articulation":null,"battery":"hyrox_v3","battery_order":2,"battery_session":"S5","category":"hyrox","created_at":"2026-10-31T23:20:25.930158+00:00","created_by":null,"description":"Maximum de wall balls en 5 min, charge et cible de sa catégorie.","fill_mode":"self","id":"00000000-0000-0000-0000-0000000000e3","is_global":true,"kind":"preset","media_url":null,"name":"Wall balls 5 min","protocol":{"text":"Charge et cible de sa catégorie (Open H 6 kg / 3,00 m, Open F 4 kg / 2,70 m, Pro H 9 kg / 3,00 m, Pro F 6 kg / 2,70 m). Quelques reps filmées de face à l''échauffement, puis 5 min au maximum. Noter les reps de chaque minute, le total, les no-reps, l''effort ressenti sur 10 et la FC 1 min après.","video":"De profil, tout le test (profondeur, cible)."},"updated_at":"2026-10-31T23:20:25.930158+00:00"},{"articulation":null,"battery":"hyrox_v3","battery_order":1,"battery_session":"W1","category":"hyrox","created_at":"2026-10-31T23:20:25.930158+00:00","created_by":null,"description":"Semaine 1 d''entraînement : endurance au Sled Push à charge de course.","fill_mode":"self","id":"00000000-0000-0000-0000-0000000000e4","is_global":true,"kind":"preset","media_url":null,"name":"Sled Push 3 × 50 m","protocol":{"text":"3 × 50 m à charge de course, 2 min de récupération. Chrono de chaque tronçon de 12,5 m (vidéo). Noter les 12 temps, l''effort ressenti sur 10 et la FC 1 min après. Protocole à valider.","video":"Tout le test, repères des 12,5 m visibles."},"updated_at":"2026-10-31T23:20:25.930158+00:00"},{"articulation":null,"battery":"hyrox_v3","battery_order":2,"battery_session":"W1","category":"hyrox","created_at":"2026-10-31T23:20:25.930158+00:00","created_by":null,"description":"Semaine 1 d''entraînement : endurance au Sled Pull à charge de course.","fill_mode":"self","id":"00000000-0000-0000-0000-0000000000e5","is_global":true,"kind":"preset","media_url":null,"name":"Sled Pull 3 × 50 m","protocol":{"text":"3 × 50 m à charge de course, 2 min de récupération. Chrono de chaque tronçon de 12,5 m (vidéo). Noter les 12 temps, l''effort ressenti sur 10 et la FC 1 min après. Protocole à valider.","video":"Tout le test, repères des 12,5 m visibles."},"updated_at":"2026-10-31T23:20:25.930158+00:00"},{"articulation":null,"battery":null,"battery_order":null,"battery_session":null,"category":"endurance","created_at":"2026-11-12T01:56:28.35658+00:00","created_by":null,"description":"FC au premier et au second seuil ventilatoire (test d''effort, labo ou terrain). Propose les zones 1 / 2 / 3 de l''athlète, à valider par le coach.","fill_mode":"coach","id":"00000000-0000-0000-0000-0000000000f1","is_global":true,"kind":"preset","media_url":null,"name":"Seuils ventilatoires (FC)","protocol":{"text":"Reporter la FC (bpm) mesurée à SV1 et à SV2. Zone 1 < SV1 ≤ Zone 2 < SV2 ≤ Zone 3."},"updated_at":"2026-11-12T01:56:28.35658+00:00"}]');

