INSERT INTO public.data_source_policies SELECT * FROM json_populate_recordset(NULL::public.data_source_policies, '[{"ai_allowed":true,"coach_visible":true,"consent_purpose":null,"notes":"Fichier fourni par l''athlète lui-même (export RGPD art. 20, FIT, TCX, GPX). Aucun accord d''API en jeu : l''API Agreement de Strava lie ses utilisateurs d''API, pas la personne qui exporte ses propres données.","source":"file_import"},{"ai_allowed":true,"coach_visible":true,"consent_purpose":null,"notes":"Saisie directe dans Agon. Aucune condition tierce.","source":"manual"},{"ai_allowed":false,"coach_visible":true,"consent_purpose":"garmin_sync","notes":"ai_allowed à false par décision du 27/10/2026, et non par obligation : la clause 4.1(b) du Connect Developer Program Agreement autorise l''affichage au coach avec le consentement de l''utilisateur, et n''interdit pas le traitement par IA. Nous nous l''interdisons quand même, pour pouvoir déclarer à Garmin une exclusion vérifiable dans le schéma plutôt qu''une intention. Revenir en arrière suppose de le dire à Garmin, pas seulement de modifier cette ligne.","source":"garmin"},{"ai_allowed":false,"coach_visible":true,"consent_purpose":"coros_sync","notes":"ai_allowed à false par précaution : les conditions COROS n''ont pas encore été relues sur ce point précis. La documentation publique ne l''interdit pas, mais une absence d''interdiction dans un README n''est pas une autorisation contractuelle — c''est exactement la confusion qui a fait perdre du temps sur Strava. Repasser à true après vérification, et le noter dans docs/DECISIONS.md.","source":"coros"}]');

